

COMMIT;






CREATE OR REPLACE PROCEDURE pr_sincronizar_identidad (
    p_nombre_tabla IN VARCHAR2
) AS
    v_column_name   user_tab_identity_cols.column_name%TYPE;
    v_sequence_name user_tab_identity_cols.sequence_name%TYPE;
    v_max_id        NUMBER;
    v_next_val      NUMBER;
BEGIN
    -- 1. Buscamos la columna identidad y la secuencia asociadas a la tabla recibida
    SELECT column_name, sequence_name
    INTO v_column_name, v_sequence_name
    FROM user_tab_identity_cols
    WHERE UPPER(table_name) = UPPER(p_nombre_tabla);

    -- 2. Obtenemos el ID más alto actual de la tabla de manera dinámica
    EXECUTE IMMEDIATE 'SELECT NVL(MAX(' || v_column_name || '), 0) FROM ' || p_nombre_tabla INTO v_max_id;

    -- 3. Avanzamos la secuencia en el bucle utilizando tu SQL dinámico real
    LOOP
        EXECUTE IMMEDIATE 'SELECT ' || v_sequence_name || '.NEXTVAL FROM DUAL' INTO v_next_val;
        EXIT WHEN v_next_val > v_max_id;
    END LOOP;

    -- Informativo en consola para verificar el resultado
    DBMS_OUTPUT.PUT_LINE('Sincronización exitosa -> Tabla: ' || UPPER(p_nombre_tabla) || ' | Próximo ID asignado: ' || (v_max_id + 1));

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('Error: La tabla "' || p_nombre_tabla || '" no existe o no tiene una columna de tipo IDENTITY.');
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error inesperado al sincronizar la tabla ' || p_nombre_tabla || ': ' || SQLERRM);
END pr_sincronizar_identidad;
COMMIT;


BEGIN 
	pr_sincronizar_identidad('ME_GUSTA');
	pr_sincronizar_identidad('RESPUESTA');
	pr_sincronizar_identidad('CUENTA');
	pr_sincronizar_identidad('LUGAR');
	pr_sincronizar_identidad('ID_RESENA');	
	COMMIT;
END;
